inline void CSApplyLegacyWeaponTuning( CCSWeaponInfo &info, CSWeaponID id )
{
	const CSLegacyWeaponTuning *t = NULL;
	for ( int i = 0; i < ARRAYSIZE( g_CSLegacyWeaponTuning ); ++i )
	{
		if ( g_CSLegacyWeaponTuning[i].id == id ) { t = &g_CSLegacyWeaponTuning[i]; break; }
	}
	if ( !t ) return;
	const float *v = t->v;
	int n = 0;
	info.m_flMaxSpeed = v[n++]; info.m_bFullAuto = v[n++] != 0.0f; info.m_iDamage = (int)v[n++]; info.m_flArmorRatio = v[n++]; info.m_iPenetration = (int)v[n++];
	info.m_flRange = v[n++]; info.m_flRangeModifier = v[n++]; info.m_iBullets = (int)v[n++]; info.m_flCycleTime[0] = v[n++]; info.m_flCycleTime[1] = v[n++];
	info.m_fSpread[0] = v[n++]; info.m_fSpread[1] = v[n++]; info.m_fInaccuracyCrouch[0] = v[n++]; info.m_fInaccuracyCrouch[1] = v[n++];
	info.m_fInaccuracyStand[0] = v[n++]; info.m_fInaccuracyStand[1] = v[n++]; info.m_fInaccuracyJump[0] = v[n++]; info.m_fInaccuracyJump[1] = v[n++];
	info.m_fInaccuracyJumpInitial[0] = v[n++]; info.m_fInaccuracyJumpInitial[1] = v[n++]; info.m_fInaccuracyLand[0] = v[n++]; info.m_fInaccuracyLand[1] = v[n++];
	info.m_fInaccuracyLadder[0] = v[n++]; info.m_fInaccuracyLadder[1] = v[n++]; info.m_fInaccuracyImpulseFire[0] = v[n++]; info.m_fInaccuracyImpulseFire[1] = v[n++];
	info.m_fInaccuracyMove[0] = v[n++]; info.m_fInaccuracyMove[1] = v[n++]; info.m_fRecoilAngle[0] = v[n++]; info.m_fRecoilAngle[1] = v[n++];
	info.m_fRecoilAngleVariance[0] = v[n++]; info.m_fRecoilAngleVariance[1] = v[n++]; info.m_fRecoilMagnitude[0] = v[n++]; info.m_fRecoilMagnitude[1] = v[n++];
	info.m_fRecoilMagnitudeVariance[0] = v[n++]; info.m_fRecoilMagnitudeVariance[1] = v[n++]; info.m_iRecoilSeed = (int)v[n++];
	info.m_fRecoveryTimeCrouch = v[n++]; info.m_fRecoveryTimeCrouchFinal = v[n++]; info.m_fRecoveryTimeStand = v[n++]; info.m_fRecoveryTimeStandFinal = v[n++];
	info.m_iRecoveryTransitionStartBullet = (int)v[n++]; info.m_iRecoveryTransitionEndBullet = (int)v[n++];
}

